-- A `COPY FROM` row enters the indexes in creation order: the plain index created first
-- refuses the oversized `a` (`54000`) before the unique one sees the duplicate `u`.
-- The harness compares SQLSTATEs only.
-- @setup
CREATE TABLE ci (a text, u int);
CREATE INDEX ci_a ON ci (a);
CREATE UNIQUE INDEX ci_u ON ci (u);
INSERT INTO ci VALUES ('x', 1);
-- @copy-from
COPY ci FROM STDIN;
-- @data
	1
-- @verify
SELECT a FROM ci;
